"""Render mobile supplemental data without changing its locale or fallback rules."""
import json
from pathlib import Path


def _dart(value):
    # JSON quoted text is valid Dart after protecting interpolation markers.
    return json.dumps(value, ensure_ascii=False).replace("$", "\\$")


def _load(package_root, name):
    document = json.loads((package_root / "catalog/mobile_supplemental" / (name + ".json")).read_text())
    if document.get("schemaVersion") != 1:
        raise ValueError("Unsupported mobile resource schema: " + name)
    return document["data"]


def render(package_root: Path, consumer_root: Path, config: dict) -> dict[str, str]:
    data = json.loads((package_root / "catalog/mobile_supplemental/index.json").read_text())
    lines = [
        "// GENERATED by im_l10n_catalog from catalog/mobile_supplemental.",
        "// Edit the versioned catalog and run tool/sync_l10n.py; do not edit here.",
        "",
        "/// Stable native names; target codes preserve the existing service contract.",
        "const translationTargetNativeNames = <String, String>{",
    ]
    for code, name in data["nativeNames"].items():
        lines.append(f"  {_dart(code)}: {_dart(name)},")
    lines += ["};", "", "/// Display names selected using the device locale, independently of App locale.",
              "const translationTargetNamesByDeviceLanguage = <String, Map<String, String>>{"]
    for locale, row in data["localizedNames"].items():
        lines.append(f"  {_dart(locale)}: {{")
        for code, name in row.items():
            lines.append(f"    {_dart(code)}: {_dart(name)},")
        lines.append("  },")
    lines += ["};", ""]
    result = {"lib/generated/l10n/translation_language_names.dart": "\n".join(lines)}
    examples = _load(package_root, "translationExamples")
    header = f"// Generated by im_l10n_catalog {config['catalogVersion']}. Do not edit.\n"
    result["lib/generated/l10n/mobile_translation_examples.dart"] = (
        header + "\nconst mobileTranslationOriginalExample = " + _dart(examples["source"]) + ";\n"
        + "const mobileTranslationExampleFallback = " + _dart(examples["fallback"]) + ";\n"
        + "const mobileTranslationExampleMessages = <String, String>" + _dart(examples["translations"]) + ";\n"
    )
    locales = _load(package_root, "supportedLocales")
    locale_lines = [header.rstrip(), "import 'dart:ui';", "", "const kSupportedLocales = ["]
    for row in locales:
        arguments = _dart(row["languageCode"])
        if row["countryCode"] is not None:
            arguments += ", " + _dart(row["countryCode"])
        locale_lines.append(f"  (Locale({arguments}), {_dart(row['nativeName'])}),")
    locale_lines += ["];", ""]
    result["lib/generated/l10n/mobile_supported_locales.dart"] = "\n".join(locale_lines)
    legal = _load(package_root, "legalDocuments")
    part = header + "part of 'package:lpp_mobile/features/settings/presentation/pages/legal_document_page.dart';\n\n"
    for name, document in legal["documents"].items():
        if not name.isidentifier():
            raise ValueError("Invalid mobile legal document declaration: " + name)
        part += f"const {name} = LegalDocumentData(\n  appBarTitle: " + _dart(document["appBarTitle"]) + ",\n  blocks: [\n"
        part += "".join("    LegalDocumentBlock(" + _dart(block) + "),\n" for block in document["blocks"])
        part += "  ],\n);\n\n"
    for symbol, value in legal["platformTexts"].items():
        if not symbol.isidentifier():
            raise ValueError("Invalid mobile legal platform text declaration: " + symbol)
        part += f"const {symbol} = " + _dart(value) + ";\n"
    result["lib/generated/l10n/mobile_legal_documents.g.dart"] = part
    for resource in data["nativeResources"]:
        result[resource["path"]] = resource["content"]
    return result
